def _rle(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + str(j - i))
        i = j
    return "".join(out)

class _Text:
    def __init__(self, s):
        self.s = s
    def __repr__(self):
        return self.s

def run_length(s):
    return _Text(_rle(s))

